import{_ as r,a0 as l,w as p,s as u,ao as s,I as d,x as n,a1 as e,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"LinuxCon大會：Google Android是開源產品 | LCTT x X-CMD","titleTemplate":false,"description":"LinuxCon大會：Google Android是開源產品 | LCTT (201309) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"LinuxCon大會：Google Android是開源產品 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"LinuxCon大會：Google Android是開源產品 | LCTT (201309) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201309/Google Android Is Open Source- LinuxCon","title":"LinuxCon大會：Google Android是開源產品","tag":"201309","desc":""},"relativePath":"201309/Google Android Is Open Source- LinuxCon.md","filePath":"[post].md"}'),a={name:"201309/Google Android Is Open Source- LinuxCon.md"};function g(x,o,m,A,C,L){const i=l("Link");return p(),u("div",null,[o[19]||(o[19]=s('<h1 id="linuxcon大會-google-android是開源產品" tabindex="-1">LinuxCon大會：Google Android是開源產品 <a class="header-anchor" href="#linuxcon大會-google-android是開源產品" aria-label="Permalink to “LinuxCon大會：Google Android是開源產品”">​</a></h1><p><em><strong>Google的首席開源執行官在LinuxCon大會上説明了為何Android是開源的以及為何開源是Android成功的關鍵因素</strong></em></p><p>9月16日，新奧爾良，LinuxCon大會，負責開源的Google董事Chris DiBona在主題演講中發佈了一條關鍵信息：Android是一款開源產品。</p><p>Google在開源社區中能夠確保不犯錯並一直遵守開源授權的要求，DiBona在這其中發揮了關鍵作用。DiBona在演講中介紹，早在2005年，從Android發展戰略剛剛開始的時候，其平台的核心基礎就是要始終保持開源。</p><p>2005年，Google面臨的困難挑戰是如何將它的搜索引擎植入手機。當時，手持設備的市場還很封閉，Google要想進入到手機市場，必須經歷一個步履維艱的過程。Google要想確保它的搜索引擎能夠輕易部署到每一部手機，在某種程度上，Android就成為了一種嘗試。</p><p>DiBona説，“我們希望人們在使用手機的時候，能擁有和電腦桌面一樣的體驗，但當時在開源領域並沒有這樣的產品”。</p><p>Google希望的是，Android只為用户提供手機所必需的基本功能，DiBona説，Google並不願因為在手機上搞競價排名或定製服務而和運營商們無休止地討價還價。</p><p>DiBona還説，“手機運營商再也不能靠捆綁銷售來競爭了，手機市場必須有一個自由環境。”</p><p>DiBona介紹，Android已經成為Google極其成功的一項成就，而且它每年都在變得更好。他還補充説，目前，新的Android設備每天的激活量已經達到130萬台。</p><p>###Linux</p>',10)),d("p",null,[o[1]||(o[1]=n("從Android利用Linux作為自身平台重要的組成部分開始，它們之間就註定結下不解之緣。2010年，Google的Android代碼被從Linux核心中",-1)),e(i,{href:"http://www.linuxplanet.com/linuxplanet/reports/7150/1/"},{default:t(()=>[...o[0]||(o[0]=[n("剔除",-1)])]),_:1}),o[2]||(o[2]=n("。",-1))]),d("p",null,[o[5]||(o[5]=n("直到2012年三月",-1)),e(i,{href:"http://www.datamation.com/open-source/linux-3.3-boosts-linux-mobility.html"},{default:t(()=>[...o[3]||(o[3]=[n("Linux內核3.3",-1)])]),_:1}),o[6]||(o[6]=n("發佈，Android才最終回到Linux核心代碼中。DiBona評論説，他始終認為Linux和Android在一起是個好主意。關於它倆是否應該在一起的爭論，這是個很技術的技術問題，涉及到一種叫做",-1)),e(i,{href:"http://developer.android.com/reference/android/os/PowerManager.WakeLock.html"},{default:t(()=>[...o[4]||(o[4]=[n("WakeLock",-1)])]),_:1}),o[7]||(o[7]=n("的省電機制。",-1))]),o[20]||(o[20]=d("p",null,"爭論先放一邊，DiBona説，有些人質疑Android是否真的開源，簡單一句話就可以證明，屢試不爽。不需要Google的參與甚至許可，任何人都可以在任何設備上安裝Android。而正是因為Google在開源許可的授權下開發了Android，以上這一切才能成為事實。",-1)),o[21]||(o[21]=d("p",null,"DiBona最後總結時強調，是開源造就了Google的Android，開源作為Android的核心觀念，早已根深蒂固。",-1)),d("p",null,[o[9]||(o[9]=n("via: ",-1)),e(i,{href:"http://www.eweek.com/mobile/google-android-is-open-source-linuxcon.html"},{default:t(()=>[...o[8]||(o[8]=[n("http://www.eweek.com/mobile/google-android-is-open-source-linuxcon.html",-1)])]),_:1})]),d("p",null,[o[12]||(o[12]=n("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...o[10]||(o[10]=[n("LCTT",-1)])]),_:1}),o[13]||(o[13]=n(" 原創翻譯，",-1)),e(i,{href:"http://linux.cn/portal.php"},{default:t(()=>[...o[11]||(o[11]=[n("Linux中國",-1)])]),_:1}),o[14]||(o[14]=n(" 榮譽推出",-1))]),d("p",null,[o[17]||(o[17]=n("譯者：",-1)),e(i,{href:"http://linux.cn/space/14801"},{default:t(()=>[...o[15]||(o[15]=[n("Mr小眼兒",-1)])]),_:1}),o[18]||(o[18]=n(" 校對：",-1)),e(i,{href:"http://linux.cn/space/14763"},{default:t(()=>[...o[16]||(o[16]=[n("Caroline",-1)])]),_:1})])])}const w=r(a,[["render",g]]);export{T as __pageData,w as default};
